ALTER TABLE ops_account_sessions DROP CONSTRAINT ops_account_sessions_state_check;
ALTER TABLE ops_account_sessions ADD CONSTRAINT ops_account_sessions_state_check CHECK(state IN('offline','login','transfer','world','cashshop'));
CREATE TABLE ops_service_leases(service text PRIMARY KEY,instance_id text NOT NULL,epoch bigint NOT NULL CHECK(epoch>0),expires_at timestamptz NOT NULL);
CREATE TABLE ops_service_transfers(
 id text PRIMARY KEY,native_handle integer NOT NULL CHECK(native_handle>0),
 target_service text NOT NULL CHECK(target_service IN('world','cashshop')),
 account_id bigint NOT NULL REFERENCES auth_accounts(id),character_id bigint NOT NULL REFERENCES game_characters(id),
 world_id integer NOT NULL,channel_id integer NOT NULL,session_id text NOT NULL,generation bigint NOT NULL,
 client_ip text NOT NULL,target_instance text NOT NULL,target_epoch bigint NOT NULL,
 expires_at timestamptz NOT NULL,consumed_at timestamptz
);
CREATE UNIQUE INDEX ops_service_transfers_pending ON ops_service_transfers(target_service,native_handle,world_id,channel_id) WHERE consumed_at IS NULL;
CREATE TABLE asset_cash_wallets(account_id bigint PRIMARY KEY REFERENCES auth_accounts(id),credit bigint NOT NULL DEFAULT 0 CHECK(credit BETWEEN 0 AND 2147483647),points bigint NOT NULL DEFAULT 0 CHECK(points BETWEEN 0 AND 2147483647),prepaid bigint NOT NULL DEFAULT 0 CHECK(prepaid BETWEEN 0 AND 2147483647));
CREATE TABLE asset_cash_items(
 id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK(id>0),account_id bigint NOT NULL REFERENCES auth_accounts(id),
 character_id bigint,world_id integer NOT NULL,sn integer NOT NULL,template_id integer NOT NULL,quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 30000),
 inv_type integer NOT NULL,slot integer NOT NULL DEFAULT 0,expires_at bigint NOT NULL DEFAULT 0,equipment jsonb,
 state text NOT NULL CHECK(state IN('locker','inventory','expired'))
);
CREATE INDEX asset_cash_items_owner ON asset_cash_items(account_id,state);
CREATE TABLE asset_cash_orders(operation_id text PRIMARY KEY,account_id bigint NOT NULL REFERENCES auth_accounts(id),character_id bigint NOT NULL REFERENCES game_characters(id),sn integer NOT NULL,currency integer NOT NULL,price bigint NOT NULL,item_id integer NOT NULL REFERENCES asset_cash_items(id),result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE asset_cash_ledger(operation_id text PRIMARY KEY,account_id bigint NOT NULL REFERENCES auth_accounts(id),currency integer NOT NULL,delta bigint NOT NULL,balance_after bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE asset_cash_moves(operation_id text PRIMARY KEY,account_id bigint NOT NULL REFERENCES auth_accounts(id),character_id bigint NOT NULL REFERENCES game_characters(id),cash_id integer NOT NULL REFERENCES asset_cash_items(id),to_locker boolean NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
